 "content": "from collections import deque


def transform(grid):
    """Recolor enclosed background cavities by area parity."""
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda color: sum(cell == color for row in grid for cell in row))
    outside = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == bg and (r, c) not in outside:
                outside.add((r, c))
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == bg and (r, c) not in outside:
                outside.add((r, c))
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg
                    and (nr, nc) not in outside):
                outside.add((nr, nc))
                q.append((nr, nc))

    out = [row[:] for row in grid]
    seen = set(outside)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cavity = []
            while q:
                x, y = q.popleft()
                cavity.append((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= nx < h and 0 <= ny < w and grid[nx][ny] == bg
                            and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            fill = 7 if len(cavity) % 2 else 2
            for x, y in cavity:
                out[x][y] = fill
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
